INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朝廷命朱全忠兼淮南节度使", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月；具体日未载", "dynasty": "唐", "description": "朝廷因淮南久乱，任朱全忠兼淮南节度使、东南面招讨使。", "phases": [], "location_name": "淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9a65023b-2b2f-569d-b6cf-ae7c66cae0e3"}, {"title": "陈敬瑄与田令孜召王建", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月前后；具体日未载", "dynasty": "唐", "description": "陈敬瑄忧顾彦朗与王建合兵图己，与田令孜商议后遣使召王建；王建赴梓州见顾彦朗，留家于梓州，率部西行。", "phases": [], "location_name": "西川、梓州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e9679c55-9afc-5775-83af-2fce0f2595d0"}, {"title": "王建率从子假子西行", "start_year": 887, "end_year": 887, "time_original": "受召后；具体日未载", "dynasty": "唐", "description": "王建率亲兵与从子、假子西行；原文具名王宗瑶、王宗弼、王宗侃、王宗弁等。", "phases": [], "location_name": "梓州至鹿头关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7f8cad93-4e9f-5b57-9c0e-5bd81ac96b12"}, {"title": "陈敬瑄拒王建过鹿头关", "start_year": 887, "end_year": 887, "time_original": "王建抵鹿头关后；具体日未载", "dynasty": "唐", "description": "一名西川参谋劝陈敬瑄勿引王建入境；陈敬瑄遣人阻止，并加强关防。王建因此愤怒。", "phases": [], "location_name": "鹿头关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b9bd906f-1dd6-5b5b-8677-8bb857a3d7e7"}, {"title": "王建破关取汉州德阳", "start_year": 887, "end_year": 887, "time_original": "被拒鹿头关后；具体日未载", "dynasty": "唐", "description": "王建破鹿头关，败汉州刺史张顼于绵竹，取汉州；进军学射山，又败西川将句惟立于蚕北，取德阳。", "phases": [], "location_name": "鹿头关、绵竹、汉州、蚕北、德阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "74bcd94f-b077-59aa-b6eb-c88ca8dfc6de"}, {"title": "王建与顾彦朗攻成都未克", "start_year": 887, "end_year": 887, "time_original": "王建取德阳后；具体日未载", "dynasty": "唐", "description": "田令孜劝慰王建未果；顾彦朗任其弟顾彦晖为汉州刺史，并发兵助王建攻成都。三日未克，王建军退屯汉州。", "phases": [], "location_name": "成都、汉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e2496b20-2a45-5909-b0e9-23685bc2133a"}, {"title": "朝廷遣使调解西川冲突", "start_year": 887, "end_year": 887, "time_original": "王建攻成都不克后；具体日未载", "dynasty": "唐", "description": "陈敬瑄向朝廷告急，朝廷遣使调解，并命人致书劝谕，但冲突双方未从。", "phases": [], "location_name": "成都、汉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "cd624e82-644a-5308-acb7-5d6b37e502a3"}, {"title": "杨行密杀高霸丁从实余绕山", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月己酉", "dynasty": "唐", "description": "杨行密听袁袭关于高霸恐反复的进言后，伏兵拘杀高霸、丁从实、余绕山，又袭杀法云寺中高霸部众。高暀出逃，次日被捕杀。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "33f81d10-477e-59bd-a944-ff02b9c41759"}, {"title": "杨行密处死吕用之及族党", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月庚戌", "dynasty": "唐", "description": "杨行密以吕用之承诺给军士的银子未兑现为由将其拘禁，命田頵讯问，随后将吕用之腰斩，并诛其族党。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "298cd5e2-9cfd-5a17-a9a7-c3f91b1e17ee"}, {"title": "吕用之讯问中出现谋杀高骈说法", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月庚戌", "dynasty": "唐", "description": "《通鉴》记田頵讯问吕用之时，有郑杞、董瑾拟借斋会杀高骈、推吕用之为节度使的说法。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "382b8bc2-baf9-5cb8-a2b0-765d462e74f2"}, {"title": "杨行密遣兵与辎重返和庐", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月甲寅至乙卯", "dynasty": "唐", "description": "袁袭因广陵饥弊、蔡军将至而建议避敌。杨行密遣延陵宗率部返和州，又命蔡俦率兵及辎重返庐州。", "phases": [], "location_name": "广陵、和州、庐州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2c0f5970-b4bd-5c14-8375-6062a72e94cf"}, {"title": "张雄攻取上元，赵晖被部下杀", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月戊午", "dynasty": "唐", "description": "赵晖据上元，与东塘张雄不通问并以兵堵江；张雄攻下上元。赵晖奔当涂途中被部下杀死。", "phases": [], "location_name": "上元、当涂", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "5547a864-d735-50dc-b6bb-94cb818f7bbe"}, {"title": "张雄坑杀赵晖降众", "start_year": 887, "end_year": 887, "time_original": "上元被攻后；具体日未载", "dynasty": "唐", "description": "赵晖余众投降张雄，张雄将其全部坑杀。", "phases": [], "location_name": "上元", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bd411a5b-ef2e-5583-98df-ad88d6d02e24"}, {"title": "朱全忠遣李璠赴淮南", "start_year": 887, "end_year": 887, "time_original": "光启三年闰月后；具体日未载", "dynasty": "唐", "description": "朱全忠遣张延范传达朝命，拟授杨行密淮南节度副使、李璠淮南留后，并遣郭言率军护送李璠。", "phases": [], "location_name": "淮南、泗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "17de1bb9-5fc5-5122-8cdc-40aa1c185be5"}, {"title": "时溥袭李璠，徐汴交恶", "start_year": 887, "end_year": 887, "time_original": "李璠至泗州时；具体日未载", "dynasty": "唐", "description": "时溥不许朱全忠军借道，在李璠抵泗州时发兵袭击；郭言力战得免而返，此后徐、汴交恶。", "phases": [], "location_name": "泗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "a5b61bf2-18b5-53c9-a477-15c2600b567d"}, {"title": "赵德諲陷荆南杀张瑰", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月癸巳", "dynasty": "唐", "description": "秦宗权所署赵德諲攻陷荆南，杀节度使张瑰，留部将王建肇守城后离开。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9a51f3d0-6fbf-5d4c-8813-95eb989d9c43"}, {"title": "陈儒陷衢州", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月；具体日未载", "dynasty": "唐", "description": "饶州刺史陈儒攻陷衢州。", "phases": [], "location_name": "衢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9a2cd4fb-d6b1-59b8-8214-cd8ac129f3a5"}, {"title": "冯敬章陷蕲州", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月；具体日未载", "dynasty": "唐", "description": "上蔡军首领冯敬章攻陷蕲州。", "phases": [], "location_name": "蕲州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4cabbccc-b443-553b-9adc-53884c9adcec"}, {"title": "周宝卒于杭州", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月乙未", "dynasty": "唐", "description": "周宝在杭州去世。", "phases": [], "location_name": "杭州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ecc55ab7-2fc8-574a-bf2f-839a795cba81"}, {"title": "钱镠任杜稜常州制置使", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月；具体日未载", "dynasty": "唐", "description": "钱镠任杜稜为常州制置使。", "phases": [], "location_name": "常州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f31c3b35-c7f6-5d2e-8bf4-e015c081d681"}, {"title": "钱镠军攻取润州擒薛朗", "start_year": 887, "end_year": 887, "time_original": "光启三年十二月丙申", "dynasty": "唐", "description": "钱镠命阮结等攻润州，丙申取城；刘浩逃走，薛朗被擒。", "phases": [], "location_name": "润州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "33ff1abe-6fc4-5495-92db-4a3ddda43423"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

