SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "朝廷因淮南久乱，任朱全忠兼淮南节度使、东南面招讨使。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p049·原文件第54行", "note": "原文：朝廷以淮南久乱，闰月，以硃全忠兼淮南节度使、东南面招讨使。；核对说明：闰月照原文，不自行断定闰几月；授官不代表已经实控淮南。", "status": "draft", "id": "db5e28c2-d995-5e9d-86b9-c7174626a6cf", "subject_id": "9a65023b-2b2f-569d-b6cf-ae7c66cae0e3", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "光启三年闰月；具体日未载", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p049·原文件第54行", "note": "原文：朝廷以淮南久乱，闰月，以硃全忠兼淮南节度使、东南面招讨使。；核对说明：闰月照原文，不自行断定闰几月；授官不代表已经实控淮南。", "status": "draft", "id": "9199531c-43c5-5de4-91f3-f21db16d146c", "subject_id": "9a65023b-2b2f-569d-b6cf-ae7c66cae0e3", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记朱温：以朱全忠名义受任者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p049·原文件第54行", "note": "原文：朝廷以淮南久乱，闰月，以硃全忠兼淮南节度使、东南面招讨使。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "0e1ed38c-81c6-5e11-a274-7966a45e771d", "subject_id": "0555e455-34d4-54ef-b93e-b0e6425018ab", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "朱温：以朱全忠名义受任者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p049·原文件第54行", "note": "原文：朝廷以淮南久乱，闰月，以硃全忠兼淮南节度使、东南面招讨使。；核对说明：按本段原文整理，不补写未载的月日、地点或人物完整生平。", "status": "draft", "id": "0a8427aa-bf08-5832-9d0a-3d2a3ad1962f", "subject_id": "287f5b37-6380-5c0c-9917-38965e4fa0f6", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "event", "field_path": "description", "claim_text": "陈敬瑄忧顾彦朗与王建合兵图己，与田令孜商议后遣使召王建；王建赴梓州见顾彦朗，留家于梓州，率部西行。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p050·原文件第55行", "note": "原文：陈敬瑄恶顾彦朗与王建相亲，恐其合兵图己，谋于田令孜，令孜曰：“建，吾子也，不为杨兴元所容，故作贼耳。今折简召之，可致麾下。”乃遣使以书召之，建大喜，诣梓州见彦朗曰：“十军阿父见召，当往省之。因见陈太师，求一大州，若得之，私愿足矣！”乃留其家于梓州，率麾精兵二千，与从子宗钅岁、假子宗瑶、宗弼、宗侃、宗弁俱西。宗瑶，燕人姜郅；宗弼，许人魏弘夫；宗侃，许人田师侃；宗弁，鹿弁也。建至鹿头关，西川参谋乂李谓敬瑄曰：“王建，虎也，奈何延之入室！彼安肯为公下乎！”敬瑄悔，亟遣人止之，且增修守备。建怒，破关而进，败汉州刺史张顼于绵竹，遂拔汉州，进军学射山，又败西川将句惟立于蚕北，又拔德阳。敬瑄遣使让之，对曰：“十军阿父召我来，乃门而拒之，重为顾公所疑，进退无归矣。”田令孜登楼慰谕之，建与诸将于清远桥上髡发罗拜，曰：“今既无归，且辞阿父作贼矣！”顾彦朗以其弟彦晖为汉州刺史，发兵助建，急攻成都，三日不克而退，还屯汉州。敬瑄告难于朝，诏遣中使和解之；又令节茂贞以书谕之，皆不从。；核对说明：陈敬瑄“恐其合兵图己”是其担忧，不作为顾彦朗、王建已结盟进攻的事实。", "status": "draft", "id": "ea994461-362e-5516-afcf-5024a165c62b", "subject_id": "e9679c55-9afc-5775-83af-2fce0f2595d0", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "光启三年闰月前后；具体日未载", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p050·原文件第55行", "note": "原文：陈敬瑄恶顾彦朗与王建相亲，恐其合兵图己，谋于田令孜，令孜曰：“建，吾子也，不为杨兴元所容，故作贼耳。今折简召之，可致麾下。”乃遣使以书召之，建大喜，诣梓州见彦朗曰：“十军阿父见召，当往省之。因见陈太师，求一大州，若得之，私愿足矣！”乃留其家于梓州，率麾精兵二千，与从子宗钅岁、假子宗瑶、宗弼、宗侃、宗弁俱西。宗瑶，燕人姜郅；宗弼，许人魏弘夫；宗侃，许人田师侃；宗弁，鹿弁也。建至鹿头关，西川参谋乂李谓敬瑄曰：“王建，虎也，奈何延之入室！彼安肯为公下乎！”敬瑄悔，亟遣人止之，且增修守备。建怒，破关而进，败汉州刺史张顼于绵竹，遂拔汉州，进军学射山，又败西川将句惟立于蚕北，又拔德阳。敬瑄遣使让之，对曰：“十军阿父召我来，乃门而拒之，重为顾公所疑，进退无归矣。”田令孜登楼慰谕之，建与诸将于清远桥上髡发罗拜，曰：“今既无归，且辞阿父作贼矣！”顾彦朗以其弟彦晖为汉州刺史，发兵助建，急攻成都，三日不克而退，还屯汉州。敬瑄告难于朝，诏遣中使和解之；又令节茂贞以书谕之，皆不从。；核对说明：陈敬瑄“恐其合兵图己”是其担忧，不作为顾彦朗、王建已结盟进攻的事实。", "status": "draft", "id": "16003b85-fb4e-56c2-bb5d-5ea6fc93ef4a", "subject_id": "e9679c55-9afc-5775-83af-2fce0f2595d0", "source_id": "9512f2c9-5083-54ad-8bd4-1ef7a3ea30e6"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记陈敬瑄：商议及遣召者。", "citation": "卷257·光启三年（887）·zztj-v257-y0887-p050·原文件第55行", "note": "原文：陈敬瑄恶顾彦朗与王建相亲，恐其合兵图己，谋于田令孜，令孜曰：“建，吾子也，不为杨兴元所容，故作贼耳。今折简召之，可致麾下。”乃遣使以书召之，建大喜，诣梓州见彦朗曰：“十军阿父见召，当往省之。因见陈太师，求一大州，若得之，私愿足矣！”乃留其家于梓州，率麾精兵二千，与从子宗钅岁、假子宗瑶、宗弼、宗侃、宗弁俱西。宗瑶，燕人姜郅；宗弼，许人魏弘夫；宗侃，许人田师侃；宗弁，鹿弁也。建至鹿头关，西川参谋乂李谓敬瑄曰：“王建，虎也，奈何延之入室！彼安肯为公下乎！”敬瑄悔，亟遣人止之，且增修守备。建怒，破关而进，败汉州刺史张顼于绵竹，遂拔汉州，进军学射山，又败西川将句惟立于蚕北，又拔德阳。敬瑄遣使让之，对曰：“十军阿父召我来，乃门而拒之，重为顾公所疑，进退无归矣。”田令孜登楼慰谕之，建与诸将于清远桥上髡发罗拜，曰：“今既无归，且辞阿父作贼矣！”顾彦朗以其弟彦晖为汉州刺史，发兵助建，急攻成都，三日不克而退，还屯汉州。敬瑄告难于朝，诏遣中使和解之；又令节茂贞以书谕之，